1	import Foundation
2	
3	/// The WebRTC data channel, with the WebRTC left out.
4	///
5	/// A seam rather than an `RTCDataChannel`: the protocol above it is plain JSON
6	/// and belongs with the rest of the daemon's vocabulary, in a module that does
7	/// not link a media framework.
8	public protocol RemoteDataChannel: Sendable {
9	    func send(_ text: String) async throws
10	    func messages() -> AsyncStream<String>
11	}
12	
13	/// A JSON value, for command payloads whose shape the caller decides.
14	public enum RemoteValue: Equatable, Sendable, Encodable {
15	    case string(String)
16	    case number(Double)
17	    case bool(Bool)
18	    case array([RemoteValue])
19	    case object([String: RemoteValue])
20	    case null
21	
22	    public func encode(to encoder: any Encoder) throws {
23	        var container = encoder.singleValueContainer()
24	        switch self {
25	        case let .string(value): try container.encode(value)
26	        case let .number(value): try container.encode(value)
27	        case let .bool(value): try container.encode(value)
28	        case let .array(values): try container.encode(values)
29	        case let .object(values): try container.encode(values)
30	        case .null: try container.encodeNil()
31	        }
32	    }
33	}
