35	/// Drives the robot over the reliable `"data"` channel of a WebRTC session.
36	///
37	/// This is the whole control surface of a remote session: the daemon's HTTP API
38	/// is not reachable from outside the robot's network, and the same commands
39	/// arrive here as JSON instead.
40	///
41	/// **There is no request id.** Most commands are answered by echoing the name
42	/// back — `{"status": "ok", "command": "wake_up", "completed": true}`, or
43	/// `{"error": "…", "command": "wake_up"}` — but a handful answer with the bare
44	/// payload and no name at all: `get_version` sends `{"version": …}`,
45	/// `get_hardware_id` sends `{"hardware_id": …}`, `get_state` sends `{"state": …}`
46	/// and both motor-mode commands send `{"motor_mode": …}`. A reply can therefore
47	/// only be attributed by something the caller supplies, which is what
48	/// `Correlation` is. Two commands sharing a token are serialised rather than
49	/// guessed at.
50	public actor RemoteControlChannel {
51	    /// How a command's reply is recognised on a channel that carries no ids.
52	    public enum Correlation: Sendable, Equatable {
53	        /// The reply echoes the command name. The common case.
54	        case echoedCommand
55	        /// The reply names nothing; this top-level key identifies it. Both
56	        /// motor-mode commands answer under `motor_mode`, so they serialise
57	        /// against each other — which is correct, since nothing tells them apart.
58	        case replyKey(String)
59	    }
60	
61	    public enum Failure: Error, Equatable, Sendable {
62	        /// The robot answered, and said no. The text is its own.
63	        case robot(String)
64	        /// Nothing came back in time. Nothing on this channel promises a deadline,
65	        /// so one is imposed here — a caller left awaiting forever is worse off
66	        /// than one told the robot went quiet.
67	        case timedOut
68	        case closed
69	    }
70	
71	    private let channel: any RemoteDataChannel
72	    private let timeout: Duration
73	    private var reader: Task<Void, Never>?
74	    /// One waiter per correlation token, which is all the wire can distinguish.
75	    private var waiting: [String: CheckedContinuation<Data, any Error>] = [:]
76	    /// Commands already in flight under the same token. Awaited in turn.
77	    private var queued: [String: [CheckedContinuation<Void, Never>]] = [:]
78	
79	    public init(channel: any RemoteDataChannel, timeout: Duration = .seconds(10)) {
80	        self.channel = channel
81	        self.timeout = timeout
82	    }
83	
84	    deinit { reader?.cancel() }
85	
86	    /// Sends a command and waits for the robot's answer.
87	    @discardableResult
88	    public func perform(
89	        _ command: String,
90	        payload: [String: RemoteValue] = [:],
91	        correlation: Correlation = .echoedCommand
92	    ) async throws -> Data {
93	        startReading()
94	        let token = switch correlation {
95	        case .echoedCommand: command
96	        case let .replyKey(key): key
97	        }
98	        await takeTurn(for: token)
99	        defer { yieldTurn(for: token) }
100	
101	        var body = payload
102	        body["type"] = .string(command)
103	        let encoded = try JSONEncoder().encode(body)
104	        guard let text = String(bytes: encoded, encoding: .utf8) else {
105	            throw EncodingError.invalidValue(body, .init(
106	                codingPath: [],
107	                debugDescription: "command payload is not UTF-8"
108	            ))
109	        }
110	
111	        // A timer that fails the waiter, rather than a task group racing the
112	        // waiter against a sleep. The group would have to await both children
113	        // before it could exit, and a continuation nothing resumes has no way to
114	        // let it — one continuation with exactly four ways to be resumed (reply,
115	        // send failure, deadline, closed channel) has no such corner.
116	        let deadline = Task { [timeout] in
117	            try? await Task.sleep(for: timeout)
118	            guard !Task.isCancelled else { return }
119	            self.expire(token)
120	        }
121	        defer { deadline.cancel() }
122	
123	        let reply = try await awaitReply(to: token, sending: text)
124	        try Self.throwIfError(in: reply)
125	        return reply
126	    }
127	
128	    private func expire(_ token: String) {
129	        waiting.removeValue(forKey: token)?.resume(throwing: Failure.timedOut)
130	    }
131	
132	    /// The same, with the answer decoded.
133	    @discardableResult
134	    public func perform<Reply: Decodable>(
135	        _ command: String,
136	        payload: [String: RemoteValue] = [:],
137	        correlation: Correlation = .echoedCommand,
138	        expecting _: Reply.Type
139	    ) async throws -> Reply {
140	        try await JSONDecoder().decode(
141	            Reply.self,
142	            from: perform(command, payload: payload, correlation: correlation)
143	        )
144	    }
145	
146	    private func awaitReply(to token: String, sending text: String) async throws -> Data {
147	        try await withCheckedThrowingContinuation { continuation in
148	            waiting[token] = continuation
149	            Task { [channel] in
150	                do {
151	                    try await channel.send(text)
152	                } catch {
153	                    self.resume(token, with: .failure(error))
154	                }
155	            }
156	        }
157	    }
158	
159	    private func startReading() {
160	        guard reader == nil else { return }
161	        reader = Task { [channel] in
162	            for await text in channel.messages() {
163	                guard !Task.isCancelled else { return }
164	                deliver(text)
165	            }
166	            failAll(with: .closed)
167	        }
168	    }
169	
170	    /// The robot also broadcasts messages nobody asked for — joint positions at
171	    /// 50 Hz, move progress, update log lines — so a message has to be routed
172	    /// before it can be delivered, and most of them are dropped here.
173	    private func deliver(_ text: String) {
174	        let data = Data(text.utf8)
175	        guard let envelope = try? JSONDecoder().decode(Envelope.self, from: data) else { return }
176	        // Every unsolicited broadcast names a `type` and no reply ever does, which
177	        // is the only thing separating `{"state": …}`, an answer, from
178	        // `{"type": "daemon_status", …, "state": …}`, which is not.
179	        guard envelope.type == nil else { return }
180	        if let command = envelope.command {
181	            resume(command, with: .success(data))
182	        } else if let token = waiting.keys.first(where: envelope.keys.contains) {
183	            resume(token, with: .success(data))
184	        }
185	    }
186	
187	    private func resume(_ token: String, with result: Result<Data, any Error>) {
188	        guard let continuation = waiting.removeValue(forKey: token) else { return }
189	        continuation.resume(with: result)
190	    }
191	
192	    private func failAll(with failure: Failure) {
193	        let pending = waiting.values
194	        waiting = [:]
195	        for continuation in pending {
196	            continuation.resume(throwing: failure)
197	        }
198	    }
199	
200	    // MARK: One command of a name at a time
201	
202	    private func takeTurn(for command: String) async {
203	        guard waiting[command] != nil || queued[command] != nil else {
204	            queued[command] = []
205	            return
206	        }
207	        await withCheckedContinuation { continuation in
208	            queued[command, default: []].append(continuation)
209	        }
210	    }
211	
212	    private func yieldTurn(for command: String) {
213	        guard var line = queued[command], !line.isEmpty else {
214	            queued[command] = nil
215	            return
216	        }
217	        let next = line.removeFirst()
218	        queued[command] = line
219	        next.resume()
220	    }
221	
222	    /// Just enough of a message to route it, without modelling every shape the
223	    /// daemon can send.
224	    private struct Envelope: Decodable {
225	        let type: String?
226	        let command: String?
227	        let keys: Set<String>
228	
229	        init(from decoder: any Decoder) throws {
230	            let container = try decoder.container(keyedBy: AnyKey.self)
231	            keys = Set(container.allKeys.map(\.stringValue))
232	            type = try? container.decodeIfPresent(String.self, forKey: AnyKey("type"))
233	            command = try? container.decodeIfPresent(String.self, forKey: AnyKey("command"))
234	        }
235	
236	        private struct AnyKey: CodingKey {
237	            let stringValue: String
238	            var intValue: Int? {
239	                nil
240	            }
241	
242	            init(_ value: String) {
243	                stringValue = value
244	            }
245	
246	            init?(stringValue: String) {
247	                self.init(stringValue)
248	            }
249	
250	            init?(intValue _: Int) {
251	                nil
252	            }
253	        }
254	    }
255	
256	    private static func throwIfError(in data: Data) throws {
257	        struct Reply: Decodable {
258	            let error: String?
259	        }
260	        if let error = try? JSONDecoder().decode(Reply.self, from: data).error, !error.isEmpty {
261	            throw Failure.robot(error)
262	        }
263	    }
264	}
