1	import Foundation
2	import ReachyKit
3	@preconcurrency import WebRTC
4	
5	/// `ReachyKit`'s `RemoteDataChannel`, carried by the real thing.
6	///
7	/// The robot opens exactly one channel, labelled `"data"`
8	/// (`media_server.py`, `create-data-channel`), and it opens it *after*
9	/// negotiation — so this exists before there is anything behind it, and a send
10	/// issued too early waits rather than fails. `RemoteControlChannel` imposes the
11	/// deadline that bounds that wait.
12	///
13	/// Untested by design, like `CameraSession`: `RTCDataChannel` cannot be stood up
14	/// outside a live peer connection. The seam that *is* tested is
15	/// `RemoteDataChannel` itself, against a scripted double.
16	public final class WebRTCDataChannel: NSObject, RemoteDataChannel, @unchecked Sendable {
17	    public enum Failure: Error, Equatable, Sendable {
18	        /// The channel took the buffer and refused it — full, or closing.
19	        case refused
20	    }
21	
22	    /// Messages that arrive before anyone is listening. Capped because the robot
23	    /// broadcasts joint positions at 50 Hz: an uncapped backlog would grow for as
24	    /// long as nothing reads it, and the oldest frame is the one worth dropping.
25	    private static let backlogLimit = 64
26	
27	    private let lock = NSLock()
28	    private var channel: RTCDataChannel?
29	    private var continuation: AsyncStream<String>.Continuation?
30	    private var backlog: [String] = []
31	    private var waitingForChannel: [CheckedContinuation<RTCDataChannel, Never>] = []
32	
33	    public func messages() -> AsyncStream<String> {
34	        AsyncStream { continuation in
35	            lock.lock()
36	            self.continuation = continuation
37	            let pending = backlog
38	            backlog = []
39	            lock.unlock()
40	            for text in pending {
41	                continuation.yield(text)
42	            }
43	        }
44	    }
45	
46	    public func send(_ text: String) async throws {
47	        let channel = await attachedChannel()
48	        let buffer = RTCDataBuffer(data: Data(text.utf8), isBinary: false)
49	        guard channel.sendData(buffer) else { throw Failure.refused }
50	    }
51	
52	    /// Called once the robot's channel is open. Anything already waiting to send
53	    /// goes out now.
54	    func attach(_ channel: RTCDataChannel) {
55	        channel.delegate = self
56	        lock.lock()
57	        self.channel = channel
58	        let waiting = waitingForChannel
59	        waitingForChannel = []
60	        lock.unlock()
61	        for continuation in waiting {
62	            continuation.resume(returning: channel)
63	        }
64	    }
65	
66	    /// The session is gone. Ends the message stream, which is what tells
67	    /// `RemoteControlChannel` to fail everything still pending.
68	    func detach() {
69	        lock.lock()
70	        channel = nil
71	        let continuation = continuation
72	        self.continuation = nil
73	        backlog = []
74	        lock.unlock()
75	        continuation?.finish()
76	    }
77	
78	    private func attachedChannel() async -> RTCDataChannel {
79	        if let channel = current() {
80	            return channel
81	        }
82	        return await withCheckedContinuation { continuation in
83	            enqueue(continuation)
84	        }
85	    }
86	
87	    /// Synchronous on purpose: `NSLock` is `noasync`, and a lock held across a
88	    /// suspension is a deadlock waiting for the right scheduling.
89	    private func current() -> RTCDataChannel? {
90	        lock.lock()
91	        defer { lock.unlock() }
92	        return channel
93	    }
94	
95	    private func enqueue(_ continuation: CheckedContinuation<RTCDataChannel, Never>) {
96	        lock.lock()
97	        // Attached between the check and here — resume rather than wait forever.
98	        if let channel {
99	            lock.unlock()
100	            continuation.resume(returning: channel)
101	            return
102	        }
103	        waitingForChannel.append(continuation)
104	        lock.unlock()
105	    }
106	
107	    private func deliver(_ text: String) {
108	        lock.lock()
109	        let listener = continuation
110	        if listener == nil {
111	            backlog.append(text)
112	            if backlog.count > Self.backlogLimit {
113	                backlog.removeFirst(backlog.count - Self.backlogLimit)
114	            }
115	        }
116	        lock.unlock()
117	        listener?.yield(text)
118	    }
119	}
120	
121	extension WebRTCDataChannel: RTCDataChannelDelegate {
122	    public func dataChannelDidChangeState(_ dataChannel: RTCDataChannel) {
123	        guard dataChannel.readyState == .closed else { return }
124	        detach()
125	    }
126	
127	    /// The daemon speaks JSON text on this channel; a binary frame is not ours.
128	    public func dataChannel(_: RTCDataChannel, didReceiveMessageWith buffer: RTCDataBuffer) {
129	        guard !buffer.isBinary, let text = String(bytes: buffer.data, encoding: .utf8) else { return }
130	        deliver(text)
131	    }
132	}
