1	import ReachyKit
2	import SwiftUI
3	
4	/// The connection attempt as ordered steps, so a failure names the step it
5	/// happened on — "the daemon never answered" and "the daemon answered but the
6	/// robot backend is down" need different things from the user.
7	///
8	/// Always a `Section`: the caller decides whether to drop it into the discovery
9	/// form (background candidate sweep) or give it a form of its own (needs a decision).
10	struct ConnectionStepper: View {
11	    let session: RobotSession
12	
13	    var body: some View {
14	        Section {
15	            ForEach(RobotSession.ConnectionStage.allCases, id: \.self, content: row)
16	            if let message = daemonMessage {
17	                Label(message, systemImage: "wrench.and.screwdriver")
18	                    .font(.callout)
19	                    .foregroundStyle(.orange)
20	            }
21	            actions
22	        } header: {
23	            Text(headerText)
24	        }
25	    }
26	
27	    private func row(for stage: RobotSession.ConnectionStage) -> some View {
28	        let outcome = session.phase.outcome(for: stage)
29	        return HStack(alignment: .firstTextBaseline, spacing: 12) {
30	            icon(for: outcome)
31	                .frame(width: 18)
32	            VStack(alignment: .leading, spacing: 2) {
33	                Text(title(for: stage))
34	                if let detail = detail(for: stage) {
35	                    Text(detail)
36	                        .font(.caption)
37	                        .foregroundStyle(.secondary)
38	                }
39	            }
40	            Spacer()
41	        }
42	    }
43	
44	    @ViewBuilder
45	    private func icon(for outcome: RobotSession.StageOutcome) -> some View {
46	        switch outcome {
47	        case .pending: Image(systemName: "circle").foregroundStyle(.secondary)
48	        case .active:
49	            ProgressView()
50	                .controlSize(.small)
51	                // SF Symbols carry a text baseline and sit on the title's line by
52	                // themselves; a spinner has none, so the row's `.firstTextBaseline`
53	                // alignment would drop it below the title. Sit it on the baseline.
54	                .alignmentGuide(.firstTextBaseline) { $0[.bottom] }
55	        case .done: Image(systemName: "checkmark.circle.fill").foregroundStyle(.green)
56	        case .attention: Image(systemName: "exclamationmark.triangle.fill").foregroundStyle(.orange)
57	        case .failed: Image(systemName: "xmark.circle.fill").foregroundStyle(.red)
58	        }
59	    }
60	
61	    @ViewBuilder
62	    private var actions: some View {
63	        if let transition = session.powerTransition {
64	            HStack(alignment: .firstTextBaseline, spacing: 12) {
65	                ProgressView().controlSize(.small)
66	                VStack(alignment: .leading, spacing: 2) {
67	                    Text(transition.statusText)
68	                    // The daemon state walks stopped → starting → running on its own
69	                    // as `waitForDaemonRunning` refreshes it: real progress, not a timer.
70	                    if let state = session.lastStatus?.state {
71	                        Text("Daemon state: \(String(describing: state))")
72	                            .font(.caption)
73	                    }
74	                }
75	                .foregroundStyle(.secondary)
76	            }
77	        } else if isBackendUnavailable {
78	            Button("Start robot backend") {
79	                Task { await session.startBackend() }
80	            }
81	            Button("Continue anyway") {
82	                session.proceedWithoutBackend()
83	            }
84	            cancelButton
85	        } else if isFailed {
86	            if let address = session.address {
87	                Button("Try again") {
88	                    Task { await session.connect(to: address) }
89	                }
90	            }
91	            cancelButton
92	        }
93	    }
94	
95	    /// `disconnect()` is the whole cancel story: it invalidates the attempt and
96	    /// pauses automatic reconnect, which is what stops the 10 s rescan from
97	    /// reopening this very card moments later.
98	    private var cancelButton: some View {
99	        Button("Cancel", role: .cancel) {
100	            session.disconnect()
101	        }
102	    }
103	
104	    private func title(for stage: RobotSession.ConnectionStage) -> String {
105	        switch stage {
106	        case .connect: "Connect to daemon"
107	        case .compatibility: "Daemon version"
108	        case .backend: "Robot backend"
109	        }
110	    }
111	
112	    private func detail(for stage: RobotSession.ConnectionStage) -> String? {
113	        guard case let .connecting(step) = session.phase else { return nil }
114	        switch step {
115	        case let .failed(failedStage, message):
116	            return failedStage == stage ? message : nil
117	        case let .needsDaemonUpdate(_, requirement):
118	            return stage == .compatibility
119	                ? "Robot runs \(requirement.reported); this app needs \(requirement.minimum)"
120	                : nil
121	        case .backendUnavailable:
122	            return stage == .backend ? "The robot backend is not running" : nil
123	        case .checkingBackend:
124	            guard stage == .backend, let state = session.lastStatus?.state else { return nil }
125	            return "Daemon state: \(String(describing: state))"
126	        case .handshaking:
127	            return nil
128	        }
129	    }
130	
131	    private var daemonMessage: String? {
132	        guard case let .connecting(.backendUnavailable(_, message)) = session.phase else { return nil }
133	        return message
134	    }
135	
136	    private var headerText: String {
137	        let target = session.address?.displayString ?? "robot"
138	        return isFailed ? "Couldn't connect to \(target)" : "Connecting to \(target)"
139	    }
140	
141	    private var isBackendUnavailable: Bool {
142	        if case .connecting(.backendUnavailable) = session.phase {
143	            return true
144	        }
145	        return false
146	    }
147	
148	    private var isFailed: Bool {
149	        if case .connecting(.failed) = session.phase {
150	            return true
151	        }
152	        return false
153	    }
154	}
