6	/// Entry point for the shared UI: connection flow → robot control, with one live
7	/// viewport placed according to how much room there is.
8	///
9	/// The tab bar lives here rather than in the app target because the Live tab and
10	/// the Robot tab share a `RobotSession` and a `ViewportModel`, and because
11	/// whether Live exists at all depends on the size class — which an `App` cannot
12	/// read. The app target's own developer screen is injected and handed to
13	/// Settings, so it keeps owning that screen without a tab or a nested tab bar.
14	public struct ReachyRootView<Developer: View>: View {
15	    private enum TabID: Hashable {
16	        case robot
17	        case live
18	        case apps
19	    }
20	
21	    @State private var session: RobotSession
22	    @State private var viewport: ViewportModel
23	    /// One Hugging Face session for the whole app, restored from the Keychain on
24	    /// launch and handed down through the environment — the account outlives any
25	    /// one robot connection, and several screens read it.
26	    @State private var hfAccount: HFAccount
27	    @State private var tab: TabID = .robot
28	    @State private var showsSettings = false
29	    /// The two ways to reach a robot are two entry points to the same list, so it
30	    /// is presented from here rather than owned by either screen that offers it.
31	    @State private var showsRemoteRobots = false
32	    /// Held for as long as the remote session is: dropping it would close the
33	    /// peer connection the session is talking over.
34	    @State private var remoteLink: RemoteRobotLink?
35	    @Environment(\.scenePhase) private var scenePhase
36	    @Environment(\.reachyPreviewMode) private var previewMode
37	
38	    #if os(macOS)
39	        /// `horizontalSizeClass` does not exist on macOS, where a window is always
40	        /// wide enough for the two-column layout.
41	        private var isCompact: Bool {
42	            false
43	        }
44	    #else
45	        @Environment(\.horizontalSizeClass) private var horizontalSizeClass
46	        private var isCompact: Bool {
47	            horizontalSizeClass == .compact
48	        }
49	    #endif
50	
51	    private let developer: Developer
52	
53	    @MainActor
54	    public init(@ViewBuilder developer: () -> Developer) {
55	        self.init(session: RobotSession(), developer: developer)
56	    }
57	
58	    /// Internal so previews can park the root in a phase a real connection would have to reach.
59	    @MainActor
60	    init(
61	        session: RobotSession,
62	        viewport: ViewportModel = ViewportModel(),
63	        hfAccount: HFAccount? = nil,
64	        @ViewBuilder developer: () -> Developer
65	    ) {
66	        _session = State(initialValue: session)
